function registerLessons(topic, stage, title, intro, scenes, check) {
  LESSONS[`${topic}-${stage}`] = {title,intro,scenes,check};
}
registerLessons('have','grund','Vad har du? Vem har det?','På svenska använder vi har. På engelska hjälper personen i meningen dig att välja have eller has.',HAVE_SCENES,{sentence:'He ___ a bike.',answer:'has',translation:'Han har en cykel.',explanation:'He hör ihop med has. Därför blir det He has a bike.'});
registerLessons('have','vidare','Långa namn. Samma koppling.','Byt namnet eller substantivet mot ett pronomen i tanken. Då blir det lättare att välja verb.',HAVE_NOUN_SCENES,{sentence:'The dogs ___ long tails.',answer:'have',translation:'Hundarna har långa svansar.',explanation:'The dogs betyder flera hundar. Byt till they: They have long tails.'});
registerLessons('have','utmaning','Hitta den som har något.','Huvudordet styr, även när en beskrivning kommer emellan.',[{...HAVE_SCENES[0],art:'box',artLabel:'En låda med flera pennor',subject:'The box',extra:'of pencils',verb:'has',end:'a lid.',bridge:'the box → it → has',title:'En låda – även med flera pennor i.',why:'Det är en box som har ett lock. Of pencils beskriver innehållet, men it → has styr verbet.',clue:'the box (of pencils) → it → has'}],{sentence:'The bag of books ___ a zip.',answer:'has',translation:'Väskan med böcker har en dragkedja.',explanation:'Det är en väska som har dragkedjan. The bag → it → has.'});
registerLessons('article','grund','En liten artikel. Ett viktigt ljud.','Titta på bilden och följ det första ljudet i det engelska ordet. A och an används här före en sak i singular.',ARTICLE_SCENES,{sentence:'___ egg',answer:'an',translation:'ett ägg',explanation:'Egg börjar med ett vokalljud. Därför blir det an egg.'});
registerLessons('article','vidare','Lyssna på ordet närmast efter luckan.','Ett adjektiv beskriver en sak: till exempel red eller old. Om det kommer efter artikeln är dess första ljud avgörande.',ARTICLE_ADJECTIVE_SCENES,{sentence:'She has ___ orange bag.',answer:'an',translation:'Hon har en orange väska.',explanation:'Orange står först efter luckan och börjar med ett vokalljud. Det blir an orange bag, även om bag börjar med b.'});
registerLessons('article','utmaning','Bokstaven kan lura dig. Ljudet avgör.','Samma bokstav kan ge olika ljud. Jämför ett stumt h med j-ljudet i university.',[
  {...ARTICLE_SCENES[0],label:'Stumt h',art:'clock',artLabel:'En klocka som visar en timme',subject:'hour',bridge:'hour → stumt h',title:'An hour. H hörs inte.',why:'Hour börjar med ett vokalljud eftersom h är stumt. Därför säger vi an hour.',translation:'en timme',clue:'hour → vokalljud → an'},
  {...ARTICLE_SCENES[1],label:'J-ljud',art:'university',artLabel:'En universitetsbyggnad',subject:'university',bridge:'university → j-ljud',title:'A university. Först kommer ett j-ljud.',why:'University börjar med ett j-ljud, som i engelskans you. Det är ett konsonantljud, trots bokstaven u. Därför blir det a university.',translation:'ett universitet',clue:'university → j-ljud → a'}
],{sentence:'It is ___ useful idea.',answer:'a',translation:'Det är en användbar idé.',explanation:'Useful börjar med ett j-ljud, som you. Därför väljer vi a.'});

